from ortools.linear_solver import pywraplp
import json

def solve_maximum_independent_set():
    N = 10

    incompatible_pairs = [
        (0, 1), (0, 2), (0, 6),
        (1, 2), (1, 9),
        (3, 4), (3, 5),
        (4, 5), (4, 9),
        (6, 7), (7, 9)
    ]

    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        print("Solver creation failed")
        return

    x = [solver.BoolVar(f"x[{i}]") for i in range(N)]

    for i, j in incompatible_pairs:
        solver.Add(x[i] + x[j] <= 1)

    objective = solver.Sum(x[i] for i in range(N))
    solver.Maximize(objective)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        selected_topics = [i for i in range(N) if x[i].solution_value() > 0.5]
        num_selected_topics = len(selected_topics)

        print(json.dumps({
            "selected_topics": selected_topics,
            "num_selected_topics": num_selected_topics
        }))
    else:
        print(f"Solver status: {status}")
        if status == pywraplp.Solver.FEASIBLE:
            print("Feasible but not optimal solution found")
        elif status == pywraplp.Solver.INFEASIBLE:
            print("Problem is infeasible")
        elif status == pywraplp.Solver.UNBOUNDED:
            print("Problem is unbounded")
        else:
            print("No solution found")

if __name__ == "__main__":
    solve_maximum_independent_set()
